head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[bigDecimal > M > calc]<br/>문자열 형태의 수학 연산식을 받아 bigDecimal 연산을 수행하고 결과를 반환합니다.",
    "validation" : [
        "expression(필수) 파라미터로 변수명과 연산자를 조합한 수학 연산식을 문자열로 설정할 수 있어야 합니다.",
        "+(덧셈), -(뺄셈), *(곱셈), /(나눗셈), ^(거듭제곱), %(나머지) 연산자를 지원해야 합니다.",
        "괄호를 사용하여 연산 우선순위를 변경할 수 있어야 합니다.",
        "연산자 우선순위는 ^(거듭제곱) > *, /, %(곱셈, 나눗셈, 나머지) > +, -(덧셈, 뺄셈) 순서로 적용되어야 합니다.",
        "피연산자가 Number 타입인 경우 자동으로 bigDecimal 타입으로 변환되어 연산되어야 합니다.",
        "피연산자가 숫자 타입이 아닌 경우 NaN 을 나타내는 bigDecimal 을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_calc_onclick = function () {
    let a = $p.bigDecimal("123456789012345678901234567890");
    let b = $p.bigDecimal("111111111111111111111111111111");
    let c = $p.bigDecimal("678901234567890123456789012345");
    let d = $p.bigDecimal("345678934567893456789345678934");
    let ret = $p.bigDecimal.calc("a + b * c + (d - a) / (c + d)");
    wf_body_bottom.getObj("scwin").setReturnValue("a + b * c + (d - a) / (c + d) : " + ret.toString());
}



scwin.btn_calcNumber_onclick = function () {
    let e = $p.bigDecimal("1234");
    let f = 3000;
    let ret = $p.bigDecimal.calc("e + f * f - f / (e + f)");
    wf_body_bottom.getObj("scwin").setReturnValue("e + f * f - f / (e + f) : " + ret.toString());
}



scwin.btn_calcOperators_onclick = function () {
    let a = $p.bigDecimal("10");
    let b = $p.bigDecimal("3");

    let retAdd = $p.bigDecimal.calc("a + b");
    wf_body_bottom.getObj("scwin").setReturnValue("a + b : " + retAdd.toString());

    let retSub = $p.bigDecimal.calc("a - b");
    wf_body_bottom.getObj("scwin").setReturnValue("a - b : " + retSub.toString());

    let retMul = $p.bigDecimal.calc("a * b");
    wf_body_bottom.getObj("scwin").setReturnValue("a * b : " + retMul.toString());

    let retDiv = $p.bigDecimal.calc("a / b");
    wf_body_bottom.getObj("scwin").setReturnValue("a / b : " + retDiv.toString());

    let retPow = $p.bigDecimal.calc("a ^ b");
    wf_body_bottom.getObj("scwin").setReturnValue("a ^ b : " + retPow.toString());

    let retMod = $p.bigDecimal.calc("a % b");
    wf_body_bottom.getObj("scwin").setReturnValue("a % b : " + retMod.toString());
}



scwin.btn_calcNaN_onclick = function () {
    let a = "abc";
    let b = $p.bigDecimal("10");
    let ret = $p.bigDecimal.calc("a + b");
    wf_body_bottom.getObj("scwin").setReturnValue("a('abc') + b(10) : " + ret.toString());
}
